Here's a sample C++ program that reads a text file line by line and counts the number of occurrences of a specific word in the file:

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <map>

int main() {
    std::string filename, word;
    int count = 0;
    std::map<std::string, int> word_count;

    // Get the filename and word to search for from the user
    std::cout << "Enter the filename: ";
    std::getline(std::cin, filename);

    std::cout << "Enter the word to search for: ";
    std::getline(std::cin, word);

    std::ifstream file(filename);
    if (!file.is_open()) {
        std::cerr << "Error: Unable to open file " << filename << std::endl;
        return 1;
    }

    std::string line;
    while (getline(file, line)) {
        // Convert the line to lowercase to make case-insensitive matching
        std::transform(line.begin(), line.end(), line.begin(), ::tolower);

        // Count the occurrences of the word in the line
        size_t pos = 0;
        while ((pos = line.find(word, pos)) != std::string::npos) {
            count++;
            pos += word.length();
        }
        // Update the word count map
        word_count[word]++;
    }

    // Print the total count of the word in the file
    std::cout << "Total occurrences of \"" << word << "\" in " << filename << ": " << count << std::endl;

    // Print the count of the word for each line (optional)
    std::cout << "Word occurrences by line:" << std::endl;
    while (getline(file, line)) {
        std::transform(line.begin(), line.end(), line.begin(), ::tolower);
        size_t pos = 0;
        int line_count = 0;
        while ((pos = line.find(word, pos)) != std::string::npos) {
            line_count++;
            pos += word.length();
        }
        std::cout << "Line: " << line << ", Word count: " << line_count << std::endl;
    }

    file.close();

    // Print the word count map (optional)
    std::cout << "Word occurrences by file:" << std::endl;
    for (const auto& entry : word_count) {
        std::cout << entry.first << ": " << entry.second << std::endl;
    }

    return 0;
}
```

This program prompts the user for the filename and the word to search for, opens the file, reads it line by line, converts the line to lowercase for case-insensitive matching, counts the occurrences of the word in the line, updates a map with the word count, prints the total count of the word in the file, prints the count of the word for each line (optional), and prints the word count map (optional).

Note that this implementation assumes that the file exists and is readable. You may want to add error handling for file opening and reading, and adjust the output format to your liking. Also, this implementation searches for exact word matches only, without considering word boundaries (e.g., it will count "cat" in "catch" as an occurrence). If you want more advanced matching options, you may want to use a library like Boost.Regex or Poco.
